        Kernel::Point_2 projected_point(plane.to_2d(Kernel::Point_3(coord[0], coord[1], coord[2])));
        auto vertex = triangulation.insert(projected_point, walk_start);
        vertex_handles.push_back(vertex);
        walk_start = vertex->face();
    }
}
for (size_t i = 0; i < vertex_handles.size(); ++i) {
    size_t next_i = (i + 1) % vertex_handles.size();
    triangulation.insert_constraint(vertex_handles[i], vertex_handles[next_i]);
}

